package main

import (
	"bytes"
	"fmt"
	"os"
	"path/filepath"
	"strings"
	"unicode"
	"unicode/utf8"
)

// strings: the Go strings, bytes and unicode/utf8 functions graphify-go calls, on 2,000
// generated byte strings. Ops that take a Go string where gostd takes &str run only on valid
// UTF-8 input (the Rust side cannot hold anything else); the byte ops run on every input.

// stringsAlphabet mixes ASCII, Latin-1, the case-folding specials, spaces of every kind, a
// combining mark, an emoji and invalid sequences (lone continuation, truncated, overlong,
// surrogate, 0xFF).
var stringsAlphabet = []string{
	"a", "Z", "k", "K", "s", "S", "0", "_", "-", ".", " ", "\t", "\n", "\v", "\f", "\r",
	"é", "É", "ß", "ẞ", " ", "\u0085", "­", "ÿ", "Ÿ", "µ", "Μ", "μ",
	"K", "İ", "ı", "Σ", "σ", "ς", "ǅ", "ǆ", "Ǆ", "ſ", "ﬃ", "Ω", "Ω", "ω", "ͅ", "ι",
	" ", " ", "　", " ", " ", "​", "́", "\U0001F600", "𐐀", "𐐨",
	"\x80", "\xff", "\xe2\x82", "\xc0\x80", "\xed\xa0\x80", "\xf0\x9f\x98", "\xef\xbf\xbd",
}

func init() {
	register("strings", 8000, func(dir string) error {
		for i := 0; i < 2000; i++ {
			name := fmt.Sprintf("s%04d", i)
			r := seed("strings/" + name)
			var b strings.Builder
			for n := r.intn(13); n > 0; n-- {
				b.WriteString(stringsAlphabet[r.intn(len(stringsAlphabet))])
			}
			if err := os.WriteFile(filepath.Join(dir, name), []byte(b.String()), 0o644); err != nil {
				return err
			}
		}
		return nil
	}, func(_ string, in []byte) []op {
		ops := []op{
			{"to_valid_utf8", result{out: []byte(strings.ToValidUTF8(string(in), "�"))}},
			{"to_valid_utf8_empty", result{out: []byte(strings.ToValidUTF8(string(in), ""))}},
			{"bytes_trim_space", result{out: bytes.TrimSpace(in)}},
			{"decode", result{out: []byte(decodeAll(in))}},
		}
		if !utf8.Valid(in) {
			return ops
		}
		s := string(in)
		folds := []string{strings.ToUpper(s), strings.ToLower(s), strings.Map(unicode.SimpleFold, s),
			"k", "K", "K", "ß", "SS", "ss", "σ", "ς", "Σ", ""}
		eq := make([]byte, len(folds))
		for i, t := range folds {
			eq[i] = bit(strings.EqualFold(s, t))
		}
		return append(ops,
			op{"to_lower", result{out: []byte(strings.ToLower(s))}},
			op{"to_upper", result{out: []byte(strings.ToUpper(s))}},
			op{"trim_space", result{out: []byte(strings.TrimSpace(s))}},
			op{"fields", result{out: []byte(strings.Join(strings.Fields(s), "\x00"))}},
			op{"equal_fold", result{out: eq}},
		)
	})
}

// decodeAll writes the DecodeRune walk forwards, the DecodeLastRune walk backwards, and
// RuneCount.
func decodeAll(b []byte) string {
	var s strings.Builder
	for i := 0; i < len(b); {
		r, w := utf8.DecodeRune(b[i:])
		fmt.Fprintf(&s, "%04X/%d ", r, w)
		i += w
	}
	s.WriteString("|")
	for j := len(b); j > 0; {
		r, w := utf8.DecodeLastRune(b[:j])
		fmt.Fprintf(&s, " %04X/%d", r, w)
		j -= w
	}
	fmt.Fprintf(&s, " | %d\n", utf8.RuneCount(b))
	return s.String()
}
